"""One prediction's mask, regenerated by the kernel that made it.

The automatic track's predictions came from `automatic_frame_result` (SAM 3.1
behind its score gate, on the frame's render, seeded by the automatic dot);
the human path's from `predict_from_jpeg` (SAM 3.1 on the stage-5.1 JPEG,
seeded by the labeled dots). Each is re-run here with the prediction's own
dot(s) on the same image, a `MaskSink` catching the kept mask, and the result
judged against what the prediction recorded (`contracts.mask_backfill.
reproduces`). Nothing else is taken from the re-run: the prediction stands.
"""

from __future__ import annotations

from typing import Any, Optional

from fishsense_services_contracts.headtail import HEADTAIL_PREDICTOR_VERSION
from fishsense_services_contracts.mask_backfill import (
    BackfillMaskFrame,
    MaskExpectation,
    reproduces,
)
from fishsense_services_contracts.masks import KEPT_MASK_STATUSES
from fishsense_services_processor.automatic_results.frames import (
    LaserDot,
    automatic_frame_result,
)
from fishsense_services_processor.headtail_predict.predict import (
    PredictOptions,
    predict_from_jpeg,
)
from fishsense_services_processor.masks import FrameMask, MaskSink

__all__ = ["regenerate"]


def regenerate(  # pylint: disable=too-many-arguments
    source: str,
    frame: BackfillMaskFrame,
    image: bytes,
    *,
    segmenter: Any,
    checkpoint: str,
    core_version: str,
) -> tuple[str, Optional[MaskExpectation], Optional[FrameMask]]:
    """``(outcome, what the re-run got, the mask when reproduced)``. Blocking.
    `segmenter` is core's `Sam3Segmenter`, which serves both paths: the
    automatic track's gate reads its ``segment_scored``, the head/tail stage
    its ``segment``."""
    sink = MaskSink()
    if source == "automatic":
        x, y = frame.dots[0]
        r = automatic_frame_result(
            capture_id=frame.capture_id,
            dot=LaserDot(float(x), float(y), 0.0, 0, None),
            jpeg_bytes=image, segmenter=segmenter, checkpoint=checkpoint,
            core_version=core_version, mask_sink=sink,
        )  # fmt: skip
    elif source == "headtail":
        r = predict_from_jpeg(
            image, frame.dots, segmenter, frame.capture_id, frame.laser_label_ids,
            PredictOptions(checkpoint=checkpoint, core_version=core_version,
                           predictor_version=HEADTAIL_PREDICTOR_VERSION),
            sink,
        )  # fmt: skip
    else:
        raise ValueError(f"no mask source {source!r}")
    if r.status == "decode_failed":
        return "decode_failed", None, None
    if r.status not in KEPT_MASK_STATUSES or sink.mask is None or r.crop_x is None:
        return "no_mask", None, None
    got = MaskExpectation(
        mask_area_px=int(r.mask_area_px), crop_x=int(r.crop_x), crop_y=int(r.crop_y),
        head_x=r.head_x, head_y=r.head_y, tail_x=r.tail_x, tail_y=r.tail_y,
    )  # fmt: skip
    if not reproduces(frame.expect, got):
        return "mismatch", got, None
    return "reproduced", got, sink.mask
